INSERT INTO public.artworks (id, title, slug, description, year, medium, category, width, height, price, sale_type, availability, featured, signature)
VALUES
  ('art-01', 'Artistic Portfolio Presentation to DGP (UP Police)', 'artistic-presentation-dgp-up-police', 'Special felicitation and artistic portfolio presentation by visual artist Dhirendra Pratap to the Director General of Police (DGP) at the Uttar Pradesh Police Headquarters, Lucknow.', 2024, 'Artistic Portfolio & Dignitary Felicitation', 'Portraits', '12 in', '16 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true),
  ('art-02', 'Contemplative Portrait Study in Graphite', 'contemplative-portrait-study', 'A delicate observational pencil portrait study of a young woman resting her chin in thoughtful repose. Drawn from life observations capturing the quiet dignity of human expression, subtle graphite gradations, and intricate hair texture.', 2022, 'Graphite on Heavyweight Archival Drawing Paper', 'Portraits', '18 in', '24 in', NULL, 'OFFER', 'AVAILABLE', true, true),
  ('art-03', 'Yellow Floral Study on Midnight Ground', 'yellow-floral-study', 'A vibrant botanical study featuring radiant yellow blooms and delicate white wildflowers painted against a deep midnight blue ground. Demonstrates energetic brushwork, atmospheric depth, and subtle colour harmony.', 2025, 'Acrylic on Canvas Board', 'Paintings', '20 in', '24 in', 42000, 'FIXED_PRICE', 'AVAILABLE', true, true),
  ('art-04', 'Observational Portrait of a Young Woman', 'portrait-young-woman-grid', 'An authentic observational pencil portrait capturing natural facial proportions, subtle graphite tonal gradations, and serene expression.', 2022, 'Pencil on Archival Drawing Paper', 'Portraits', '16 in', '20 in', NULL, 'OFFER', 'AVAILABLE', true, false),
  ('art-05', 'Traditional Folk Mud Wall Mural', 'traditional-folk-mud-wall-mural', 'Monumental textured mural combining natural clays, mineral ochres, and traditional Indian rural motifs. Created for an architectural heritage installation celebrating vernacular village life.', 2022, 'Clay, Straw, Cow Dung & Mineral Pigments on Prepared Wall', 'Wall Art', '120 in', '96 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true),
  ('art-06', 'Urban Civic Retaining Wall Mural', 'urban-civic-retaining-wall-mural', 'Civic public art beautification mural executed on exterior concrete retaining walls. Features bold stylized typography, local flora, and dynamic abstract geometries.', 2023, 'Exterior Weather-Resistant Pigments & Acrylic on Concrete', 'Wall Art', '240 in', '108 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true),
  ('art-07', 'Monumental Transformer Reclaimed Metal Sculpture', 'monumental-transformer-sculpture', 'A colossal humanoid robotic sculpture engineered entirely from salvaged automotive scrap, discarded vehicle chassis, gears, and structural steel.', 2023, 'Welded Automotive & Industrial Scrap Metal', 'Scrap Craft', '72 in', '144 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true),
  ('art-08', 'Ceremonial Dignitary Welcome Rangoli', 'ceremonial-dignitary-welcome-rangoli', 'Photographic documentation of a grand ceremonial floor rangoli and fresh flower carpet created by Dhirendra for the official visit of Uttar Pradesh Chief Minister Yogi Adityanath.', 2023, 'Natural Dry Pigments, Sacred Powders & Fresh Floral Petals', 'Rangoli', '144 in', '144 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, false),
  ('art-09', 'COVID-19 Awareness Street Rangoli — "Stay Home"', 'covid19-awareness-street-rangoli', 'Monumental civic street art created on asphalt during the 2020 pandemic in Lucknow in collaboration with Civil Defence and the Journalist Association.', 2020, 'Civic Powder Pigments on City Asphalt', 'Rangoli', '216 in', '216 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true),
  ('art-10', 'Monumental Elephant Foam Art Sculpture', 'monumental-elephant-sculpture', 'A life-sized, anatomically modeled elephant sculpture carved meticulously from high-density EPS foam and thermocol.', 2023, 'High-Density EPS Foam, Acrylic Gesso & Metallic Patina', 'Foam Art', '96 in', '84 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true),
  ('art-11', 'Lion Head Architectural Relief Sculpture', 'lion-head-relief-sculpture', 'High-relief animalier sculpture depicting the ferocious countenance of a roaring lion.', 2023, 'Carved EPS Foam, Plaster Composite & Bronze Finish', 'Foam Art', '36 in', '48 in', NULL, 'OFFER', 'AVAILABLE', true, true),
  ('art-12', 'Commissioned Dignitary Portrait Presentation', 'commissioned-dignitary-portrait-presentation', 'Special felicitation and ceremonial presentation of a commissioned portrait by artist Dhirendra Pratap to a distinguished dignitary.', 2022, 'Commissioned Portrait & Felicitation Ceremony', 'Portraits', '24 in', '30 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true),
  ('art-13', 'Portrait Presentation to Hon''ble CM Yogi Adityanath', 'portrait-presentation-cm-yogi-adityanath', 'Special felicitation and ceremonial presentation of a custom-framed fine art portrait directly to Uttar Pradesh Chief Minister Yogi Adityanath by artist Dhirendra Pratap.', 2023, 'Commissioned Portrait & Ceremonial Felicitation', 'Portraits', '24 in', '32 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true),
  ('art-14', 'Architectural Wall Art Installation 48', 'architectural-wall-art-installation-48', 'Site-specific architectural wall mural executed as part of public cultural beautification and heritage enhancement projects in Uttar Pradesh.', 2024, 'Exterior Weather-Resistant Pigments & Acrylic on Prepared Concrete', 'Wall Art', '192 in', '96 in', NULL, 'NOT_FOR_SALE', 'ARCHIVED', true, true)
