INSERT INTO public.achievements (title, organization, year, category, location, description, featured)
VALUES
  ('Lalit Kala Akademi National ''Har Ghar Tiranga'' Workshop', 'Lalit Kala Akademi Regional Centre Lucknow (Ministry of Culture, Govt. of India)', 2022, 'National Awards', 'Lucknow, Uttar Pradesh', 'Certificate of participation and merit awarded to Dhirendra Pratap by Regional Secretary Dr. Devendra Tripathi during the national Har Ghar Tiranga visual arts workshop.', true),
  ('Uttar Pradesh Kala Ratna', 'Afadul Hasan Welfare Society', 2020, 'State Awards', 'Lucknow, Uttar Pradesh', 'Conferred to Dhirendra Pratap on 28.06.2020 in recognition of exceptional service to visual fine arts and cultural documentation.', true),
  ('Kala Shree Samman & COVID-19 Public Art Honor', 'U.P. District Recognized Journalist Association', 2020, 'District / DM Recognition', 'Lucknow, Uttar Pradesh', 'Special felicitation and citation presented for pioneering street rangolis and public art murals in Lucknow promoting pandemic awareness and honoring frontline workers.', true),
  ('University of Lucknow South Asia Wall Map Citation', 'Department of Western History, University of Lucknow', 2022, 'Government Recognition', 'Lucknow, India', 'Certificate of appreciation from Dean Prof. Prem Suman Sharma and HOD Prof. Madhu Rajput recognizing the creation of the monumental South Asia Wall Map in the department.', true),
  ('Shan-e-Siddharth (Urdu Daily) Fine Arts Citation', 'Shan-e-Siddharth Daily / Shoeb Khan, Editor-in-Chief', 2021, 'Other Honours', 'Lucknow / Siddharth Nagar, Uttar Pradesh', 'Formal citation and certificate of appreciation commending Dhirendra Pratap for his extraordinary contributions and dedication to painting (Chitrakala).', true),
  ('COVID-19 Warrior Cultural Felicitation', 'Mankameshwar Math Mandir (Mahant Devyagiri)', 2020, 'Exhibitions', 'Lucknow, Uttar Pradesh', 'Felicitation on World Dance Day at Mankameshwar Math Mandir for creating public awareness wall paintings during the lockdown across Lucknow.', true),
  ('State Lalit Kala Akademi Youth Art Workshop', 'State Lalit Kala Akademi Uttar Pradesh', 2012, 'Art Competitions', 'Ballia, Uttar Pradesh', 'Foundational workshop and merit recognition during early artistic training in Ballia, under the auspices of the State Lalit Kala Akademi.', true)
